/** biome-ignore-all lint/suspicious/noConsole: event handlers run outside the application logger */
import { connect } from "cloudflare:sockets";
// @ts-expect-error generated by OpenNext before packaging the Worker
import openNextWorker from "../.open-next/worker.js";
import prismaQueryCompiler from "../generated/prisma-workers/internal/query_compiler_fast_bg.wasm?module";
import {
  dispatchCloudflareRequest,
  type CloudflareBindings,
  type WorkerExecutionContext,
} from "../utils/cloudflare/context";
import { scheduledRoutesDueAt } from "../utils/cron/schedule";
import {
  consumeCloudflareJobs,
  type CloudflareQueueBatch,
} from "../utils/queue/cloudflare-consumer";

// workerd requires the query compiler to be compiled at deployment time.
globalThis.__prismaQueryCompiler = prismaQueryCompiler;

function fetchApplication(
  request: Request,
  env: CloudflareBindings,
  ctx: WorkerExecutionContext,
  queueDelivery = false,
  verifiedWebhook = false,
) {
  return dispatchCloudflareRequest(
    request,
    env,
    ctx,
    (request, bindings, context) =>
      openNextWorker.fetch(request, bindings, context),
    { connect, queueDelivery, verifiedWebhook },
  );
}

export default {
  fetch: fetchApplication,

  async scheduled(event: { scheduledTime: number }, env: CloudflareBindings) {
    if (!env.JOBS || !env.CRON_SECRET || !env.INTERNAL_API_KEY) {
      throw new Error(
        "Scheduled work requires JOBS, CRON_SECRET and INTERNAL_API_KEY",
      );
    }
    for (const route of scheduledRoutesDueAt(new Date(event.scheduledTime))) {
      await env.JOBS.send({ method: "GET", path: route.path, topic: "cron" });
    }
  },

  async queue(
    batch: CloudflareQueueBatch,
    env: CloudflareBindings,
    ctx: WorkerExecutionContext,
  ) {
    await consumeCloudflareJobs({
      batch,
      bindings: env,
      dispatch: (request, verifiedWebhook) =>
        fetchApplication(request, env, ctx, true, verifiedWebhook),
      report: (message, context) => console.error(message, context),
    });
  },
};
